def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]
        success = False

        if verb == "undo" and len(tokens) == 1:
            if history:
                action = history.pop()
                kind = action[0]

                if kind == "open":
                    del balances[action[1]]
                    frozen.discard(action[1])
                elif kind == "deposit":
                    balances[action[1]] -= action[2]
                elif kind == "withdraw":
                    balances[action[1]] += action[2]
                elif kind == "transfer":
                    balances[action[1]] += action[3]
                    balances[action[2]] -= action[3]
                elif kind == "freeze":
                    frozen.remove(action[1])
                else:
                    frozen.add(action[1])

                success = True

        elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
            account = tokens[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append((verb, account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append((verb, account))
                    success = True

        elif (
            verb in ("open", "deposit", "withdraw", "transfer")
            and len(tokens) == (4 if verb == "transfer" else 3)
        ):
            amount_text = tokens[-1]
            if amount_text and all("0" <= c <= "9" for c in amount_text):
                # Parse in chunks to support amounts of arbitrary length.
                amount = 0
                for start in range(0, len(amount_text), 9):
                    chunk = amount_text[start:start + 9]
                    amount = amount * (10 ** len(chunk)) + int(chunk)

                account = tokens[1]
                if verb == "open":
                    if account not in balances:
                        balances[account] = amount
                        history.append((verb, account))
                        success = True
                elif verb == "deposit":
                    if amount > 0 and account in balances:
                        balances[account] += amount
                        history.append((verb, account, amount))
                        success = True
                elif verb == "withdraw":
                    if (
                        amount > 0
                        and account in balances
                        and account not in frozen
                        and balances[account] >= amount
                    ):
                        balances[account] -= amount
                        history.append((verb, account, amount))
                        success = True
                else:
                    target = tokens[2]
                    if (
                        amount > 0
                        and account != target
                        and account in balances
                        and target in balances
                        and account not in frozen
                        and balances[account] >= amount
                    ):
                        balances[account] -= amount
                        balances[target] += amount
                        history.append((verb, account, target, amount))
                        success = True

        if not success:
            rejected.append(index)

    return balances, rejected
